            py = get_any(x, ["y", "row", "cy", "j"], None)
            if px is not None and py is not None:
                return (px, py)
        return None

    def scan_positions(obj):
        pts = []
        if obj is None:
            return pts
        if isinstance(obj, dict):
            p = as_pair(obj)
            if p is not None:
                pts.append(p)
            for v in obj.values():
                pts.extend(scan_positions(v))
        elif isinstance(obj, (list, tuple)):
