        resources.extend(scan_positions(get_any(observation, [key], None)))

    for key in ["enemies", "enemy", "opponents", "opponent", "hostiles", "threats"]:
        enemies.extend(scan_positions(get_any(observation, [key], None)))

    for key in ["allies", "ally", "teammates", "team"]:
        allies.extend(scan_positions(get_any(observation, [key], None)))

    for key in ["goals", "goal", "bases", "base", "home", "homes", "territory"]:
        goals.extend(scan_positions(get_any(observation, [key], None)))

    # Grid / map occupancy if provided
    grid = get_any(observation, ["grid", "board", "map", "arena", "world"], None)

    # Determine move preferences
    cand_moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best = (0, 0)
    best_score = None

    # Heuristic state
    hp = get_any(me, ["hp", "health", "energy", "stamina"], None)
