        return score

    for m in cand_moves:
        s = score_move(m)
        if best_score is None or s > best_score:
            best_score = s
            best = m

    dx, dy = best

    # If selected move is dangerous and a safer alternative exists, choose it
    if enemies:
        best_danger = 0
        for ex, ey in enemies:
            if abs((my_pos[0] + dx) - ex) + abs((my_pos[1] + dy) - ey) <= 1:
